package servicio;
import api.publica.NotificacionComunidadDTO.*;import config.ConexionBD;import java.sql.*;import java.time.LocalDateTime;import java.util.*;
public final class NotificacionComunidadService {
 public Bandeja listar(long clienteId){validar(clienteId);try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{proyectar(c);List<Notificacion> items=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT id,tipo,titulo,mensaje,recurso_tipo,recurso_id,url_contextual,fecha_creacion,fecha_lectura FROM comunidad_notificaciones WHERE cliente_destinatario_id=? ORDER BY fecha_creacion DESC,id DESC LIMIT 50")){s.setLong(1,clienteId);try(ResultSet r=s.executeQuery()){while(r.next())items.add(map(r));}}long pendientes=contar(c,clienteId);c.commit();return new Bandeja(List.copyOf(items),pendientes,items.size());}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudieron consultar las notificaciones.",e);}}
 public Lectura leer(long clienteId,long id){validar(clienteId);if(id<=0)throw new IllegalArgumentException("La notificacion es obligatoria.");try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{proyectar(c);LocalDateTime fecha=null;try(PreparedStatement q=c.prepareStatement("SELECT fecha_lectura FROM comunidad_notificaciones WHERE id=? AND cliente_destinatario_id=? FOR UPDATE")){q.setLong(1,id);q.setLong(2,clienteId);try(ResultSet r=q.executeQuery()){if(!r.next())throw new NotificacionNoEncontradaException();Timestamp t=r.getTimestamp(1);fecha=t==null?LocalDateTime.now():t.toLocalDateTime();}}try(PreparedStatement u=c.prepareStatement("UPDATE comunidad_notificaciones SET fecha_lectura=COALESCE(fecha_lectura,?),version=version+IF(fecha_lectura IS NULL,1,0) WHERE id=? AND cliente_destinatario_id=?")){u.setTimestamp(1,Timestamp.valueOf(fecha));u.setLong(2,id);u.setLong(3,clienteId);u.executeUpdate();}c.commit();return new Lectura(id,fecha,true);}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo marcar la notificacion como leida.",e);}}
 public LecturaTodas leerTodas(long clienteId){validar(clienteId);try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{proyectar(c);int n;try(PreparedStatement s=c.prepareStatement("UPDATE comunidad_notificaciones SET fecha_lectura=NOW(),version=version+1 WHERE cliente_destinatario_id=? AND fecha_lectura IS NULL")){s.setLong(1,clienteId);n=s.executeUpdate();}c.commit();return new LecturaTodas(n,0);}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudieron actualizar las notificaciones.",e);}}
 private void proyectar(Connection c)throws SQLException{String q="INSERT IGNORE INTO comunidad_notificaciones(cliente_destinatario_id,evento_id,tipo,titulo,mensaje,recurso_tipo,recurso_id,url_contextual,fecha_creacion) "+
 "SELECT cc.cliente_creador_id,e.id,e.tipo,'Nueva solicitud para tu turno','Una persona quiere sumarse a tu convocatoria.','SOLICITUD',e.solicitud_id,CONCAT('/w2/comunidad/convocatoria?convocatoriaId=',e.convocatoria_id),e.fecha_evento FROM comunidad_eventos e JOIN comunidad_convocatorias cc ON cc.id=e.convocatoria_id WHERE e.tipo='SOLICITUD_RECIBIDA' AND e.solicitud_id IS NOT NULL "+
 "UNION ALL SELECT p.cliente_id,e.id,e.tipo,CASE e.tipo WHEN 'SOLICITUD_ACEPTADA' THEN 'Tu solicitud fue aceptada' ELSE 'Tu solicitud fue rechazada' END,CASE e.tipo WHEN 'SOLICITUD_ACEPTADA' THEN 'Ya formas parte del turno abierto.' ELSE 'La convocatoria continuo con otra persona.' END,'SOLICITUD',e.solicitud_id,CONCAT('/w2/comunidad/convocatoria?convocatoriaId=',e.convocatoria_id),e.fecha_evento FROM comunidad_eventos e JOIN comunidad_solicitudes s ON s.id=e.solicitud_id JOIN perfiles_jugador p ON p.id=s.perfil_solicitante_id WHERE e.tipo IN ('SOLICITUD_ACEPTADA','SOLICITUD_RECHAZADA') "+
 "UNION ALL SELECT cc.cliente_creador_id,e.id,e.tipo,'El turno ya esta completo','La convocatoria alcanzo los cuatro participantes.','CONVOCATORIA',e.convocatoria_id,CONCAT('/w2/comunidad/convocatoria?convocatoriaId=',e.convocatoria_id),e.fecha_evento FROM comunidad_eventos e JOIN comunidad_convocatorias cc ON cc.id=e.convocatoria_id WHERE e.tipo='CONVOCATORIA_COMPLETA' "+
 "UNION ALL SELECT p.cliente_id,e.id,e.tipo,CASE e.tipo WHEN 'CONVOCATORIA_COMPLETA' THEN 'El turno completo sus lugares' WHEN 'CONVOCATORIA_CERRADA_EXTERNAMENTE' THEN 'La convocatoria fue cerrada' WHEN 'CONVOCATORIA_CANCELADA' THEN 'La convocatoria fue cancelada' ELSE 'La convocatoria vencio' END,CASE e.tipo WHEN 'CONVOCATORIA_COMPLETA' THEN 'El turno se completo con otras personas.' WHEN 'CONVOCATORIA_CERRADA_EXTERNAMENTE' THEN 'El titular completo el turno fuera de la plataforma.' WHEN 'CONVOCATORIA_CANCELADA' THEN 'La reserva o convocatoria ya no continua.' ELSE 'El turno comenzo o la convocatoria llego a su vencimiento.' END,'CONVOCATORIA',e.convocatoria_id,CONCAT('/w2/comunidad/convocatoria?convocatoriaId=',e.convocatoria_id),e.fecha_evento FROM comunidad_eventos e JOIN comunidad_solicitudes s ON s.convocatoria_id=e.convocatoria_id JOIN perfiles_jugador p ON p.id=s.perfil_solicitante_id WHERE (e.tipo='CONVOCATORIA_COMPLETA' AND s.estado='CERRADA_POR_CUPO') OR (e.tipo IN ('CONVOCATORIA_CERRADA_EXTERNAMENTE','CONVOCATORIA_CANCELADA') AND s.estado='CERRADA_POR_CONVOCANTE') OR (e.tipo='CONVOCATORIA_VENCIDA' AND s.estado='VENCIDA') "+
 "UNION ALL SELECT pd.cliente_id,e.id,e.tipo,'Recibiste una invitacion deportiva','Revisa la propuesta y responde desde tu cuenta.','INVITACION',e.invitacion_id,'/w2/cuenta?seccion=deporte',e.fecha_evento FROM comunidad_eventos e JOIN comunidad_invitaciones i ON i.id=e.invitacion_id JOIN perfiles_jugador pd ON pd.id=i.perfil_destinatario_id WHERE e.tipo='INVITACION_COMUNIDAD_ENVIADA' "+
 "UNION ALL SELECT pe.cliente_id,e.id,e.tipo,CASE e.tipo WHEN 'INVITACION_COMUNIDAD_ACEPTADA' THEN 'Aceptaron tu invitacion' ELSE 'Rechazaron tu invitacion' END,CASE e.tipo WHEN 'INVITACION_COMUNIDAD_ACEPTADA' THEN 'Ya podes consultar el contacto protegido.' ELSE 'La propuesta quedo cerrada.' END,'INVITACION',e.invitacion_id,'/w2/cuenta?seccion=deporte',e.fecha_evento FROM comunidad_eventos e JOIN comunidad_invitaciones i ON i.id=e.invitacion_id JOIN perfiles_jugador pe ON pe.id=i.perfil_emisor_id WHERE e.tipo IN ('INVITACION_COMUNIDAD_ACEPTADA','INVITACION_COMUNIDAD_RECHAZADA') "+
 "UNION ALL SELECT pd.cliente_id,e.id,e.tipo,'La invitacion fue cancelada','La propuesta ya no esta disponible.','INVITACION',e.invitacion_id,'/w2/cuenta?seccion=deporte',e.fecha_evento FROM comunidad_eventos e JOIN comunidad_invitaciones i ON i.id=e.invitacion_id JOIN perfiles_jugador pd ON pd.id=i.perfil_destinatario_id WHERE e.tipo='INVITACION_COMUNIDAD_CANCELADA' "+
 "UNION ALL SELECT p.cliente_id,e.id,e.tipo,'La invitacion vencio','La propuesta llego a su fecha de vencimiento.','INVITACION',e.invitacion_id,'/w2/cuenta?seccion=deporte',e.fecha_evento FROM comunidad_eventos e JOIN comunidad_invitaciones i ON i.id=e.invitacion_id JOIN perfiles_jugador p ON p.id=CASE WHEN e.actor_perfil_id=i.perfil_emisor_id THEN i.perfil_destinatario_id ELSE i.perfil_emisor_id END WHERE e.tipo='INVITACION_COMUNIDAD_VENCIDA'";try(Statement st=c.createStatement()){st.executeUpdate(q);}}
 private Notificacion map(ResultSet r)throws SQLException{Timestamp l=r.getTimestamp("fecha_lectura");LocalDateTime lectura=l==null?null:l.toLocalDateTime();long rid=r.getLong("recurso_id");return new Notificacion(r.getLong("id"),r.getString("tipo"),r.getString("titulo"),r.getString("mensaje"),r.getString("recurso_tipo"),r.wasNull()?null:rid,r.getString("url_contextual"),r.getTimestamp("fecha_creacion").toLocalDateTime(),lectura,lectura!=null);}
 private long contar(Connection c,long cliente)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM comunidad_notificaciones WHERE cliente_destinatario_id=? AND fecha_lectura IS NULL")){s.setLong(1,cliente);try(ResultSet r=s.executeQuery()){r.next();return r.getLong(1);}}}
 private void validar(long id){if(id<=0)throw new IllegalArgumentException("El cliente es invalido.");}private void rollback(Connection c,Exception e){try{c.rollback();}catch(SQLException x){e.addSuppressed(x);}}private void auto(Connection c){try{c.setAutoCommit(true);}catch(SQLException ignored){}}
 public static final class NotificacionNoEncontradaException extends IllegalArgumentException{public NotificacionNoEncontradaException(){super("La notificacion no existe.");}}
}
